const { vec } = NMath;
const { x: spiral } = IO.loadSpiralData({ turns: 0.5 });
const targets = spiral;
const bounds = [0, 1].map(axis => [
    Math.min(...spiral.map(point => point.components[axis])),
    Math.max(...spiral.map(point => point.components[axis])),
]);
const randomPoint = () => vec(...bounds.map(([min, max]) => min + Math.random() * (max - min)));
const initial = Array.from({ length: targets.length }, randomPoint);

// Entropic optimal transport (Sinkhorn) gives a plan; each source goes straight to its barycentric match.
const ot = OptimalTransport.new(
    { points: initial },
    { points: targets },
    { entropy: 0.002 },
).fit();
console.log(`Sinkhorn iterations: ${ot.iterations}, transport cost: ${ot.cost().toFixed(4)}`);

const plot = IO.plotPointCloud(targets, { aspect: "equal", radius: 0.012, color: [0.4, 0.4, 0.4] });
const moving = plot.add(initial, { radius: 0.015, color: [1, 0, 0] });
// Invisible anchors keep the coordinate system fixed as the cloud moves.
plot.add([[-1.2, -1.2], [1.2, 1.2]], { color: [0, 0, 0] });

const showTime = t => {
    moving.update(ot.interpolate(t), { color: [1 - t, t, 0] });
    plot.render();
};

const ui = IO.UI(
    { type: "canvas", value: () => plot },
    {
        type: "slider", value: () => ({
            title: "t:", min: 0, max: 1, step: 0.01, value: 0,
            onChange: showTime,
        })
    },
);
showTime(0);
ui;
